  font-size: 85%;
}

.form-control {
  font-size: 100%;
  line-height: 1.25;
}

.custom-select {
  height: calc(2.25rem - 2px);
  margin-right: 0px !important;
}

.tight-label {
  margin-right: 3px !important;
}

.custom-input {
  margin-right: 0px !important;
}

.btn {
  margin: 0.25rem;
}

input[type='file'] {
  width: 200px;
}

.dropdown {
  width: 100%;
  margin-right: 0 !important;
}

@media (min-width: 576px) {
  .dropdown {
    width: auto;
  }
}

/* the div containing the tubemap svg */
#tubeMapSVG {
  position: relative;
  margin: 20px;
  border: 1px solid rgba(0, 0, 0, 0.125);
  border-radius: 0.25rem;
  overflow: hidden;
}

#svg {
  width: 100%;
  height: 75vh;
  overflow: visible;
}

/* contains the spinning loader */
#loaderContainer {
  margin: 0 auto;
  padding: 40px;
}

/* spinning loader during graph construction */
#loader {
  border: 5px solid #f3f3f3;
  animation: spin 1s linear infinite;
  border-top: 5px solid #555;
  border-radius: 50%;
  width: 50px;
  height: 50px;
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

/* spinning loader covering the "Go"-button during file uploads */
.smallLoader {
  border: 5px solid #f3f3f3;
  animation: spin 1s linear infinite;
  border-top: 5px solid #555;
  border-radius: 50%;
  width: 30px;
  height: 30px;
  z-index: 1;
  position: relative;
  left: 21px;
  margin-right: -21px;
  background-color: #6fa9fb;
}

/* small colored squares which are part of the graph's legen */
.color-box {
  width: 15px;
  height: 15px;
  display: inline-block;
  background-color: #ccc;
  left: 5px;
  top: 5px;
}

.btn-secondary {
  background-color: #868e96;
  border-color: #868e96;
}

.btn-secondary:hover {
  background-color: #727b84;
  border-color: #6c757d;
}

.custom-input {
  height: calc(2.25rem - 2px);
}

/* for the help popup */
.popup {
  position: relative;
  display: inline-block;
  cursor: pointer;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.popup .popuptext {
  visibility: hidden;
  width: 300px;
  background-color: #555;
  color: #fff;
  text-align: center;
  border-radius: 6px;
  padding: 8px 0;
  position: absolute;
  z-index: 1;
  top: 125%;
  left: 50%;
  margin-left: -80px;
}

/* .popup .popuptext::after { */
/*   content: ""; */
/*   position: absolute; */
/*   bottom: 100%; */
/*   left: 50%; */
/*   margin-left: -5px; */
/*   border-width: 5px; */
/*   border-style: solid; */
/*   border-color: #555 transparent transparent transparent; */
/* } */

.popup .show {
  visibility: visible;
  animation: fadeIn 1s;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.tracklist-button {
  display: flex;
  align-items: left;
  justify-content: left;
  height: 100%;
  margin-left: 10px;
}

.tracklist-dropdown {
  margin-top: 4px;
}

/* Close Popup */

.closePopup {
  align-items: center;
  scale: 0.7;
  border-radius: 50%;
  position: absolute;
  top: -20px;
  right: -20px;
}

.help-dialog-icon {
  opacity: 0.45;
  transition:
    opacity 0.15s ease,
    color 0.15s ease;
}

.help-dialog-icon:hover {
  opacity: 1;
  color: #0d6efd;
}

.radio-row {
  /*max-width: max-content;  for some reason doesn't work for haplotype settings row */
  max-width: 680px; /* TODO: would like to make this flexible? */
  margin-top: 10px;
}
